    if last_boxed:
        last_boxed_res = remove_boxed(last_boxed).replace('\\text{', '').replace('}', '').replace('\\', '').lower()
        if last_boxed_res in {'a', 'b', 'c', 'd', 'e'}:
            parsed_answer = last_boxed_res
        if parsed_answer == ground_truth.lower():
